 let ng=3+v*.1,vol=.0005+v*.00002,a=.025,b=.000027,real=ng*8.314*298.15/(vol-ng*b)-a*(ng/vol)**2;
 num('vdw',v,'gas','real-gas',3,`Hydrogen: n=${ng.toFixed(2)} mol, V=${(vol*1000).toFixed(3)} L, T=298.15 K. Use a=0.025 Pa·m⁶/mol², b=2.7×10⁻⁵ m³/mol and R=8.314 Pa·m³ mol⁻¹ K⁻¹. Find the van der Waals pressure.`,real,[[ng*8.314*298.15/vol,"The ideal formula was used without corrections a, b."],[ng*8.314*298.15/(vol-ng*b)+a*(ng/vol)**2,"Attraction reduces pressure: the correction a(n/V)² is subtracted."],[a*(ng/vol)**2,"This is only the attraction correction, not the total pressure."]],[`V=${vol.toExponential(3)} m³, V−nb=${(vol-ng*b).toExponential(3)} m³ >0.`,`P=nRT/(V−nb)−a(n/V)²=${fmt(real,'Pa')}.`],'Pa');
