 let heat=45+v*3,work=15+v;
 num('first-law',v,'thermo','energy',1,`A gas absorbs ${heat} kJ of heat and does ${work} kJ of work on its surroundings. Calculate ΔU for the gas.`,heat-work,[[heat+work,"The work of the system on the environment has a negative sign in ΔU=q+w."],[-heat-work,"Absorbed heat is positive."],[work-heat,"Signs refer to the system, not the environment."]],[`q=+${heat}, w=−${work} kJ.`,`ΔU=q+w=${heat-work} kJ.`],'kJ');
 let mol=5+v*.5,qh=1050+v*100,dt=qh/(mol*18.015*4.18);
