 let kg=.8+v*.2,below=10+v,phase=kg*(2.11*below+333.6+4.18*100+2257);
 num('snow',v,'thermo','phase',3,`Convert ${kg.toFixed(1)} kg of ice at −${below} °C into steam at 100 °C. Use c_ice=2.11 and c_water=4.18 kJ kg⁻¹ K⁻¹, L_fus=333.6 and L_vap=2257 kJ/kg. How much heat is required?`,phase,[[kg*4.18*(100+below),"Only heating with an incorrect constant heat capacity is taken into account, phase transitions are forgotten."],[phase-kg*333.6,"Missed melting."],[phase-kg*2257,"Missed evaporation at 100°C."]],[`Ice heating: ${fmt(kg*2.11*below,'kJ')}; melting: ${fmt(kg*333.6,'kJ')}.`,`Water heating: ${fmt(kg*418,'kJ')}; evaporation: ${fmt(kg*2257,'kJ')}.`,`Total = ${fmt(phase,'kJ')}.`],'kJ');
 let sample=.2+v*.02,cap=3500+v*100,rise=1.6+v*.1,energy=cap*rise/1000/(sample/60);
 num('bomb',v,'thermo','enthalpy',2,`A ${sample.toFixed(3)} g sample (M=60.0 g/mol) is burned in a bomb calorimeter. The TOTAL heat capacity is ${cap} J/K and temperature rises ${rise.toFixed(2)} K. Calculate the molar ΔU of combustion.`,-energy,[[energy,"The question asks for the ΔU of the reaction, not the positive value of released energy. The reaction gives off heat."],[-cap*rise/1000,"This is the heat of combustion of the sample, not one mole."],[-energy/1000,"J have already been converted to kJ. Do not convert a second time."]],[`q_rxn=−C_totalΔT=${fmt(-cap*rise/1000,'kJ')}.`,`n=m/M=${fmt(sample/60,'mol')}.`,`ΔU_m=q_rxn/n=${fmt(-energy,'kJ/mol')}.`],'kJ/mol');
 let pe=1.5+v*.1,vi=8+v,vf=20+v*2,w=-pe*(vf-vi)*101.325;
 num('pv-work',v,'thermo','gas-thermo',2,`An ideal gas follows two steps: it expands from ${vi} L to ${vf} L against a constant external pressure of ${pe.toFixed(1)} atm, then changes pressure at constant volume. Find total chemical-sign work w. 1 L·atm=101.325 J.`,w,[[-w,"When expanding, w is negative in chemical convention."],[w/101.325,"This is a numerical value in L·atm, not J."],[-pe*vf*101.325,"We need ΔV=V_f−V_i, not the full final volume."]],[`On the isochore w₂=0.`,`w_total=−P_ext(V_f−V_i)=${fmt(w,'J')}.`],'J');
