 let amount=.5+v*.15,dh=255.95*amount;
 num('hess-calc',v,'thermo','hess',2,`For CH₄(g)+NH₃(g)→HCN(g)+3H₂(g), ΔH°f values (kJ/mol) are: CH₄ −74.9; NH₃ −45.9; HCN +135.15; H₂ 0. Calculate ΔH when ${amount.toFixed(2)} mol of CH₄ reacts completely with excess NH₃.`,dh,[[-dh,"Products and reactants are mixed up."],[255.95,"This is ΔH per 1 mol CH₄; the quantity in the problem is different."],[(135.15-74.9-45.9)*amount,"Negative enthalpies of reactants must be subtracted with parentheses."]],[`ΔH_rxn=135.15−(−74.9−45.9)=255.95 kJ per 1 mol CH₄.`,`q=${amount.toFixed(2)}×255.95=${fmt(dh,'kJ')}.`],'kJ');
