 let c0=.4+v*.05,K=2.25+v*.25,r=Math.sqrt(K),x=c0*(r-1)/(r+1),prod=c0+x;
 num('ice-calc',v,'eq','ice',3,`For A(g)+B(g)⇌C(g)+D(g), Kc=${K.toFixed(2)}. Initially each gas has concentration ${c0.toFixed(2)} M. Find [C] at equilibrium.`,prod,[[x,"x is the change in concentration; add the original [C]₀."],[c0-x,"This is the concentration of reagent A or B."],[c0*(K-1)/(K+1)+c0,"We need to take √K since the concentration ratio is squared."]],[`ICE: A,B=c₀−x; C,D=c₀+x.`,`√K=(c₀+x)/(c₀−x); x=c₀(√K−1)/(√K+1)=${fmt(x,'M')}.`,`[C]=c₀+x=${fmt(prod,'M')}.`],'M');
 let kp=.25+v*.025,temp=1100+v*10,kc=kp*.082057*temp;
 num('kp',v,'eq','shifts',2,`For 2SO₂(g)+O₂(g)⇌2SO₃(g), Kp=${kp.toFixed(3)} at ${temp} K. Using the classroom Kp=Kc(RT)^Δn convention with R=0.082057 L·atm mol⁻¹ K⁻¹, find Kc.`,kc,[[kp/(.082057*temp),"Δn=−1, so K_c=K_p RT, not K_p/(RT)."],[kp,"K_p=K_c only at Δn=0 (or a special numerical RT)."],[kp*(.082057*temp)**2,"The change in gas moles is −1, not −2."]],[`Δn_gas=2−(2+1)=−1.`,`K_p=K_c/(RT); K_c=K_p RT=${fmt(kc)}.`]);
 let ka=(1+v*.2)*1e-5,conc=.1+v*.02,h=2*ka*conc/(ka+Math.sqrt(ka*ka+4*ka*conc)),ph=-Math.log10(h);
